package com.google.gson.stream;

import com.google.gson.stream.JsonWriter;
import java.io.*;
import java.io.Closeable;
import java.io.Flushable;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertThrows;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

public class JsonWriter_value_TriageGen1Test {

    @Test
    public void testValue_Nan() throws IOException {
        StringWriter out = new StringWriter();
        JsonWriter jsonWriter = new JsonWriter(out);
        assertThrows(IllegalArgumentException.class, () -> jsonWriter.value(Double.NaN));
    }

    @Test
    public void testValue_Infinite() throws IOException {
        StringWriter out = new StringWriter();
        JsonWriter jsonWriter = new JsonWriter(out);
        assertThrows(IllegalArgumentException.class, () -> jsonWriter.value(Double.POSITIVE_INFINITY));
    }

    @Test
    public void testValue_Normal() throws IOException {
        StringWriter out = new StringWriter();
        JsonWriter jsonWriter = new JsonWriter(out);
        jsonWriter.value(123.456);
        assertEquals("123.456", out.toString());
    }

    @Test
    public void testValue_Null() throws IOException {
        StringWriter out = new StringWriter();
        JsonWriter jsonWriter = new JsonWriter(out);
        jsonWriter.value(null);
        assertEquals("null", out.toString());
    }

    @Test
    public void testValue_String() throws IOException {
        StringWriter out = new StringWriter();
        JsonWriter jsonWriter = new JsonWriter(out);
        jsonWriter.value("Hello, World!");
        assertEquals("\"Hello, World!\"", out.toString());
    }

    @Test
    public void testValue_Null_Then_Normal() throws IOException {
        StringWriter out = new StringWriter();
        JsonWriter jsonWriter = new JsonWriter(out);
        jsonWriter.value(null);
        jsonWriter.value(123.456);
        assertEquals("null123.456", out.toString());
    }

    @Test
    public void testValue_Normal_Then_Null() throws IOException {
        StringWriter out = new StringWriter();
        JsonWriter jsonWriter = new JsonWriter(out);
        jsonWriter.value(123.456);
        jsonWriter.value(null);
        assertEquals("123.456null", out.toString());
    }

    @Test
    public void testValue_Normal_Then_Normal() throws IOException {
        StringWriter out = new StringWriter();
        JsonWriter jsonWriter = new JsonWriter(out);
        jsonWriter.value(123.456);
        jsonWriter.value(789.012);
        assertEquals("123.456789.012", out.toString());
    }

    @Test
    public void testValue_Null_Then_Null() throws IOException {
        StringWriter out = new StringWriter();
        JsonWriter jsonWriter = new JsonWriter(out);
        jsonWriter.value(null);
        jsonWriter.value(null);
        assertEquals("nullnull", out.toString());
    }
}
